set -uo pipefail
mkdir -p /logs/verifier

[ -e "/home/workspace/p2/T1.cpp" ] || echo "WARNING: submission missing: /home/workspace/p2/T1.cpp"
[ -e "/home/workspace/p2/T2.cpp" ] || echo "WARNING: submission missing: /home/workspace/p2/T2.cpp"
[ -e "/home/workspace/p2/T3.cpp" ] || echo "WARNING: submission missing: /home/workspace/p2/T3.cpp"
[ -e "/home/workspace/p2/T4.cpp" ] || echo "WARNING: submission missing: /home/workspace/p2/T4.cpp"
[ -e "/home/workspace/p2/T5.cpp" ] || echo "WARNING: submission missing: /home/workspace/p2/T5.cpp"
[ -e "/home/workspace/p2/T6.cpp" ] || echo "WARNING: submission missing: /home/workspace/p2/T6.cpp"

cd /home/workspace/p2
OUT=$(cd /home/workspace/p2 && python3 /opt/p2_judge/prob/P2/eval.py --source-root /home/workspace/p2 --time-factor 1 --time-grace 0 --score-sum 2>&1)
EC=$?
